const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../lib/storage-parts.cjs');
test('path components retain their documented meanings', () => {
  for (const [p, expected] of [
    ['/srv/images/card.png/', {root:'/',dir:'/srv/images',base:'card.png',ext:'.png',name:'card'}],
    ['notes/.local', {root:'',dir:'notes',base:'.local',ext:'',name:'.local'}],
    ['a/../b.csv', {root:'',dir:'a/..',base:'b.csv',ext:'.csv',name:'b'}],
    ['plan.', {root:'',dir:'',base:'plan.',ext:'.',name:'plan'}],
    ['/', {root:'/',dir:'/',base:'',ext:'',name:''}],
    ['', {root:'',dir:'',base:'',ext:'',name:''}]
  ]) assert.deepEqual(app.storageParts(p), expected);
});

